func LowerBound(xs []int, target int) int {
	lo, hi := 0, len(xs)
	for lo < hi {
		mid := lo + (hi-lo)/2
		if xs[mid] < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

func TwoSum(xs []int, target int) (int, int, bool) {
	seen := make(map[int]int)
	for j, x := range xs {
		if i, ok := seen[target-x]; ok {
			return i, j, true
		}
		seen[x] = j
	}
	return 0, 0, false
}

func UniqueBytes(s string) int {
	last := make(map[byte]int)
	left, best := 0, 0
	for right := 0; right < len(s); right++ {
		if p, ok := last[s[right]]; ok && p >= left {
			left = p + 1
		}
		last[s[right]] = right
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	return best
}

// adj contains integer node IDs; all edges have unit cost.
func Distances(adj [][]int, start int) []int {
	d := make([]int, len(adj))
	for i := range d {
		d[i] = -1
	}
	d[start] = 0
	q := []int{start}
	for head := 0; head < len(q); head++ {
		v := q[head]
		for _, w := range adj[v] {
			if d[w] != -1 {
				continue
			}
			d[w] = d[v] + 1
			q = append(q, w)
		}
	}
	return d
}

type Edge struct{ To, Weight int }
type candidate struct{ Node, Cost int }
type candidates []candidate

func (h candidates) Len() int           { return len(h) }
func (h candidates) Less(i, j int) bool { return h[i].Cost < h[j].Cost }
func (h candidates) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *candidates) Push(x any)        { *h = append(*h, x.(candidate)) }
func (h *candidates) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// Requires container/heap. Caller validates node IDs, nonnegative
// weights and that every path cost fits int. -1 means unreachable.
func ShortestDistances(adj [][]Edge, start int) []int {
	d := make([]int, len(adj))
	for i := range d {
		d[i] = -1
	}
	d[start] = 0
	h := &candidates{{Node: start, Cost: 0}}
	for h.Len() > 0 {
		current := heap.Pop(h).(candidate)
		if current.Cost != d[current.Node] {
			continue
		}
		for _, e := range adj[current.Node] {
			cost := current.Cost + e.Weight
			if d[e.To] < 0 || cost < d[e.To] {
				d[e.To] = cost
				heap.Push(h, candidate{Node: e.To, Cost: cost})
			}
		}
	}
	return d
}

type minInts []int

func (h minInts) Len() int           { return len(h) }
func (h minInts) Less(i, j int) bool { return h[i] < h[j] }
func (h minInts) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minInts) Push(x any)        { *h = append(*h, x.(int)) }
func (h *minInts) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// Requires imports container/heap and sort.
func TopK(xs []int, k int) []int {
	if k <= 0 {
		return nil
	}
	h := &minInts{}
	for _, x := range xs {
		if h.Len() < k {
			heap.Push(h, x)
		} else if x > (*h)[0] {
			(*h)[0] = x
			heap.Fix(h, 0)
		}
	}
	out := append([]int(nil), (*h)...)
	sort.Ints(out)
	return out
}

func Merge(a, b []int) []int {
	out := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			out = append(out, a[i])
			i++
		} else {
			out = append(out, b[j])
			j++
		}
	}
	out = append(out, a[i:]...)
	return append(out, b[j:]...)
}

func MinCoins(coins []int, amount int) int {
	dp := make([]int, amount+1) // caller validates positive coins and bounded amount
	for x := 1; x <= amount; x++ {
		dp[x] = amount + 1
		for _, c := range coins {
			if c <= x && dp[x-c]+1 < dp[x] {
				dp[x] = dp[x-c] + 1
			}
		}
	}
	if dp[amount] > amount {
		return -1
	}
	return dp[amount]
}

// Caller validates every node ID and bounds graph size.
func TopologicalOrder(adj [][]int) ([]int, bool) {
	degree := make([]int, len(adj))
	for _, edges := range adj {
		for _, v := range edges {
			degree[v]++
		}
	}
	queue := make([]int, 0, len(adj))
	for v, n := range degree {
		if n == 0 {
			queue = append(queue, v)
		}
	}
	order := make([]int, 0, len(adj))
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		order = append(order, u)
		for _, v := range adj[u] {
			degree[v]--
			if degree[v] == 0 {
				queue = append(queue, v)
			}
		}
	}
	if len(order) != len(adj) {
		return nil, false
	}
	return order, true
}

type DisjointSet struct {
	parent, size []int
	Components   int
}

// Caller supplies a nonnegative n and valid IDs to Find and Union.
func NewDisjointSet(n int) *DisjointSet {
	d := &DisjointSet{parent: make([]int, n), size: make([]int, n), Components: n}
	for i := range d.parent {
		d.parent[i] = i
		d.size[i] = 1
	}
	return d
}
func (d *DisjointSet) Find(x int) int {
	for x != d.parent[x] {
		d.parent[x] = d.parent[d.parent[x]]
		x = d.parent[x]
	}
	return x
}
func (d *DisjointSet) Union(a, b int) bool {
	a, b = d.Find(a), d.Find(b)
	if a == b {
		return false
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	d.parent[b] = a
	d.size[a] += d.size[b]
	d.Components--
	return true
}

// Requires container/list. This cache has a single owner; it is not concurrent.
type lruEntry struct{ key, value int }
type LRU struct {
	capacity int
	order    *list.List
	entries  map[int]*list.Element
}

func NewLRU(capacity int) *LRU {
	if capacity < 0 {
		capacity = 0
	}
	return &LRU{capacity: capacity, order: list.New(), entries: make(map[int]*list.Element)}
}
func (c *LRU) Get(key int) (int, bool) {
	element, ok := c.entries[key]
	if !ok {
		return 0, false
	}
	c.order.MoveToFront(element)
	return element.Value.(lruEntry).value, true
}
func (c *LRU) Put(key, value int) {
	if c.capacity == 0 {
		return
	}
	if element, ok := c.entries[key]; ok {
		element.Value = lruEntry{key, value}
		c.order.MoveToFront(element)
		return
	}
	c.entries[key] = c.order.PushFront(lruEntry{key, value})
	if c.order.Len() > c.capacity {
		oldest := c.order.Back()
		delete(c.entries, oldest.Value.(lruEntry).key)
		c.order.Remove(oldest)
	}
}

type Interval struct{ Start, End int }

// Closed intervals; caller validates Start<=End. Does not mutate input.
func MergeIntervals(input []Interval) []Interval {
	xs := append([]Interval(nil), input...)
	sort.Slice(xs, func(i, j int) bool {
		if xs[i].Start == xs[j].Start {
			return xs[i].End < xs[j].End
		}
		return xs[i].Start < xs[j].Start
	})
	var out []Interval
	for _, x := range xs {
		if len(out) == 0 || x.Start > out[len(out)-1].End {
			out = append(out, x)
			continue
		}
		if x.End > out[len(out)-1].End {
			out[len(out)-1].End = x.End
		}
	}
	return out
}

