import "fmt"

type State string

const (
	Reserved  State = "reserved"
	Charged   State = "charged"
	Refunding State = "refunding"
	Done      State = "done"
)

func next(s State, event string) (State, error) {
	switch {
	case s == Reserved && event == "charged":
		return Charged, nil
	case s == Charged && event == "shipping-failed":
		return Refunding, nil
	case s == Refunding && event == "refund-confirmed":
		return Done, nil
	}
	return s, fmt.Errorf("unexpected %s in %s", event, s)
}
func main() {
	s, _ := next(Charged, "shipping-failed")
	fmt.Println(s) // refunding, not done
	s, err := next(s, "refund-confirmed")
	fmt.Println(s, err)
}

