import (
	"fmt"
	"math/big"
	"strings"
)

func units(text string, scale uint8) (*big.Int, error) {
	if scale > 36 || len(text) > 80 {
		return nil, fmt.Errorf("input budget")
	}
	p := strings.Split(text, ".")
	if len(p) > 2 || p[0] == "" {
		return nil, fmt.Errorf("decimal required")
	}
	frac := ""
	if len(p) == 2 {
		frac = p[1]
		if frac == "" {
			return nil, fmt.Errorf("empty fraction")
		}
	}
	if len(frac) > int(scale) {
		return nil, fmt.Errorf("precision exceeds scale")
	}
	digits := p[0] + frac
	for _, c := range digits {
		if c < '0' || c > '9' {
			return nil, fmt.Errorf("digits only")
		}
	}
	value, ok := new(big.Int).SetString(digits+strings.Repeat("0", int(scale)-len(frac)), 10)
	if !ok || value.BitLen() > 256 {
		return nil, fmt.Errorf("amount out of range")
	}
	return value, nil
}
func main() { n, err := units("1.000000000000000001", 18); fmt.Println(n, err) }

