type Block struct {
	Height       uint64
	Hash, Parent string
}

func appendBlock(chain []Block, b Block) ([]Block, error) {
	if len(chain) > 0 {
		tip := chain[len(chain)-1]
		if b.Height != tip.Height+1 || b.Parent != tip.Hash {
			return chain, fmt.Errorf("reconcile canonical ancestor before append")
		}
	}
	return append(chain, b), nil
}
func main() {
	chain := []Block{{Height: 10, Hash: "A10", Parent: "A9"}}
	chain, _ = appendBlock(chain, Block{Height: 11, Hash: "A11", Parent: "A10"})
	_, err := appendBlock(chain, Block{Height: 11, Hash: "B11", Parent: "A10"})
	fmt.Println(err) // replacement is not silently appended
}

