type Principal struct{ Subject, Tenant, Role string }
type Document struct{ Tenant, Owner string }

func canRead(p Principal, d Document) bool {
	return p.Subject != "" && p.Tenant == d.Tenant && (p.Subject == d.Owner || p.Role == "auditor")
}
