type Config struct{ limits map[string]int }

func publish(dst *atomic.Pointer[Config], src map[string]int) {
	copied := make(map[string]int, len(src))
	for k, v := range src {
		copied[k] = v
	}
	dst.Store(&Config{limits: copied})
}
func main() {
	var current atomic.Pointer[Config]
	input := map[string]int{"workers": 4}
	publish(&current, input)
	input["workers"] = 99
	snapshot := current.Load()
	fmt.Println(snapshot.limits["workers"]) // 4
}

