import (
	"fmt"
	"sync"
)

type Cache struct {
	mu     sync.Mutex
	values map[string]int
}

func (c *Cache) Put(k string, v int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.values == nil {
		c.values = map[string]int{}
	}
	c.values[k] = v
}
func (c *Cache) Snapshot() map[string]int {
	c.mu.Lock()
	defer c.mu.Unlock()
	out := make(map[string]int, len(c.values))
	for k, v := range c.values {
		out[k] = v
	}
	return out
}
func main() {
	var c Cache
	c.Put("a", 1)
	copy := c.Snapshot()
	copy["a"] = 99
	fmt.Println(c.Snapshot()["a"])
}

