import "fmt"

func nextOffset(start int64, done map[int64]bool) int64 {
	for done[start] {
		start++
	}
	return start
}
func main() {
	done := map[int64]bool{11: true, 13: true}
	fmt.Println(nextOffset(11, done)) // 12: cannot skip unfinished 12
	done[12] = true
	fmt.Println(nextOffset(11, done)) // 14: resume after the completed prefix
}

