import "fmt"

type Node struct {
	Value int
	Next  *Node
}

func entry(head *Node) *Node {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
		if slow == fast {
			p := head
			for p != slow {
				p = p.Next
				slow = slow.Next
			}
			return p
		}
	}
	return nil
}
func main() {
	a, b, c := &Node{Value: 1}, &Node{Value: 2}, &Node{Value: 3}
	a.Next = b
	b.Next = c
	c.Next = b
	fmt.Println(entry(a) == b, entry(nil) == nil)
}

