import (
	"crypto/sha256"
	"encoding/binary"
	"fmt"
)

func owner(key string, nodes []string) string {
	best := ""
	var high uint64
	for _, node := range nodes {
		sum := sha256.Sum256([]byte(fmt.Sprintf("%d:%s%d:%s", len(key), key, len(node), node)))
		score := binary.BigEndian.Uint64(sum[:8])
		if best == "" || score > high || (score == high && node < best) {
			best = node
			high = score
		}
	}
	return best
}
func main() {
	fmt.Println(owner("order-7", []string{"a", "b", "c"}) == owner("order-7", []string{"c", "a", "b"}))
}

